#!/usr/bin/env bash
# Writes ansible/inventory.ini from the Terraform outputs. The file is gitignored (real IPs).
set -euo pipefail
ROOT="$(git rev-parse --show-toplevel)"
OUT="$ROOT/ansible/inventory.ini"
KEY="$ROOT/.private/ssh/id_ed25519"

IPS="$(terraform -chdir="$ROOT/iac" output -json vm_ips)"
ip() {
  local v
  v="$(jq -r --arg n "$1" '.[$n] // empty' <<<"$IPS")"
  if [[ -z "$v" || "$v" == null ]]; then
    echo "gen-inventory: no IP for $1 (is the VM running?)" >&2
    exit 1
  fi
  printf '%s' "$v"
}

umask 022
cat >"$OUT" <<INV
# Generated by scripts/gen-inventory.sh from terraform output. Do not edit by hand.
[docker_host]
c3-docker-host ansible_host=$(ip c3-docker-host)

[k8s_master]
c3-k8s-master ansible_host=$(ip c3-k8s-master)

[k8s_workers]
c3-k8s-worker-1 ansible_host=$(ip c3-k8s-worker-1)
c3-k8s-worker-2 ansible_host=$(ip c3-k8s-worker-2)

[k8s_cluster:children]
k8s_master
k8s_workers

[all:vars]
ansible_user=devops
ansible_ssh_private_key_file=$KEY
INV
echo "gen-inventory: wrote ansible/inventory.ini (IPs and key path, no secrets)"
